function templateCurrent(template){const teamIds=template.teamIds.filter(id=>state.people.some(p=>p.personId===id&&!p.archived)),config=structuredClone(template.config);for(const k of ['equipment','games','program'])config[k]=(config[k]||[]).map(r=>({...r,hostId:teamIds.includes(r.hostId)?r.hostId:''}));config.stations=(config.stations||[]).map(s=>{const ids=(s.operatorIds||[]).filter(id=>teamIds.includes(id));return {...s,operatorIds:ids,assignmentRequired:s.assignmentRequired||!!s.operatorIds?.length&&!ids.length};});if(config.map?.layout)config.map.layout.booths=config.map.layout.booths.map(b=>({...b,personIds:(b.personIds||[]).filter(id=>teamIds.includes(id))}));return {template,resourceReview:template.resourceReview,event:{eventId:template.templateId,title:template.name,description:template.description,teamIds,date:'',time:'',venue:'',visibility:'private',revision:template.revision,app:{state:'closed',hasDraft:true}},experience:{...config,revision:template.revision}};}
