async function route(){
  if(!state.user)return;
  const version=++routeVersion,requested=location.hash;
  if(integrated&&(state.busy||mapEditor?.busy||document.querySelector('dialog[open]'))){history.replaceState(null,'',location.pathname+lastRoute);toast('Bitte schließe zuerst den aktuellen Vorgang ab.');return;}
  if(websiteEditor?.busy){history.replaceState(null,'',location.pathname+lastRoute);toast('Bitte warte, bis der aktuelle Vorgang abgeschlossen ist.');return;}
  if(mapEditor?.dirty&&!await confirmDiscard()){history.replaceState(null,'',location.pathname+lastRoute);return;}
  if(websiteEditor?.dirty&&!await confirmDiscard()){history.replaceState(null,'',location.pathname+lastRoute);return;}
  if(version!==routeVersion)return;
  websiteEditor?.destroy();websiteEditor=null;clearMapEditor();
  if(integrated)root.querySelector('#workspace')?.setAttribute('aria-busy','true');
  if(websiteChanged){await loadData();websiteChanged=false;}
  if(version!==routeVersion)return;
  const hash=!hasEventAccess()&&isAuthor()?'website/posts':location.hash.slice(1)||(integrated&&isEditor()?'templates':'events'),parts=hash.split('/');
  state.filter='all';state.search='';
  if(['event','template'].includes(parts[0])&&parts[1]&&(parts[0]!=='template'||isEditor())){state.page='event';state.tab=['overview','offers','drinks','team','stations','map'].includes(parts[2])?parts[2]:'overview';if(state.current?.event.eventId!==parts[1])await loadCurrent(parts[1],version,parts[0]==='template');}
  else if(parts[0]==='plan'&&parts[1]&&isEditor()){state.page='venueplan';const {plan}=await api('/api/abend/venue-plans/'+encodeURIComponent(parts[1]));state.current={plan,event:{eventId:plan.planId,title:plan.name,teamIds:[]},experience:{equipment:[],games:[],program:[],menu:[],stations:[],map:{enabled:false,asHome:true,title:plan.name,layout:plan.layout}}};}
  else {state.page=['reports','history','more','venueplans','library','people','live','accounts','templates','pictures','team',...(integrated?['website']:[])].includes(parts[0])?parts[0]:'events';state.current=null;}
  if(!hasEventAccess()&&isAuthor()&&state.page!=='website'){state.page='website';state.websiteSection='posts';}
  if(integrated&&state.page==='live'){location.replace('/live');return;}
  if(state.page==='website'){state.websiteSection=['posts','events','team'].includes(parts[1])?parts[1]:'posts';if(!isEditor()&&!isAuthor())state.page='denied';if(isAuthor()&&!isEditor())state.websiteSection='posts';}
  if(integrated&&state.current?.event&&!state.current.template&&!state.current.plan)sessionStorage.setItem('rudelbar:backstage:event',state.current.event.eventId);
  if(state.page==='accounts'){if(!isAdmin())state.page='events';else await accountsUI.load();}
  if(['library','people','templates','pictures','team','venueplans'].includes(state.page)&&!isEditor())state.page='events';
  if(state.page==='library'){state.contentTab=['items','categories','trash','stands','tasks','stock','relationships'].includes(parts[1])?parts[1]:'items';if(['stands','tasks','stock','relationships'].includes(state.contentTab))await resourceUI.load();}
  if(state.page==='reports'){if(!hasReportAccess())state.page='denied';else await reportingUI.load(parts[1]);}
  if(state.page==='pictures'){state.pictureScope=parts[1]==='website'?'website':'app';await contentUI.loadPictures();}
  if(['team','people','accounts'].includes(state.page)){state.teamTab=state.page==='accounts'?'accounts':state.page==='people'?'people':parts[1]||'people';if(!['people','partners','accounts','roles','settings'].includes(state.teamTab)||!isAdmin()&&['accounts','roles','settings'].includes(state.teamTab))state.teamTab='people';if(state.teamTab==='accounts'&&isAdmin())await accountsUI.load();state.page='team';}
  if((isEditor()&&state.page==='venueplan'||state.page==='event'&&['offers','map'].includes(state.tab)))await resourceUI.load();
  if(version!==routeVersion)return;lastRoute=requested;render();window.scrollTo({top:0,behavior:'instant'});
}
function navLinks(){return [['events','calendar-days','Abende'],...(isEditor()?[['library','layout-grid','Inhalte'],['people','users-round','Personen']]:[]),['live','radio','Live'],...(isAdmin()?[['accounts','user-round-cog','Benutzer']]:[])].map(([page,ic,label])=>`<a href="#${page}" ${state.page===page||(page==='events'&&state.page==='event')?'aria-current="page"':''}>${icon(ic)}<span>${label}</span></a>`).join('');}
