 const pages=[...(isEditor()||isAuthor()?[['website','globe-2',isAuthor()&&!isEditor()?'Beiträge':'Webseite']]:[]),...(hasEventAccess()?[[isEditor()?'templates':'events','layout-template','Gäste-App']]:[]),...(isEditor()?[['library','layout-grid','Unser Angebot'],['pictures','images','Bilder'],['team/people','users-round','Team']]:[]),...(hasReportAccess()?[['reports','chart-no-axes-combined','Auswertung']]:[]),...(isAdmin()?[['team/accounts','settings','Verwaltung']]:[])];
